/**
 * Turns a *validated* Read More blueprint into the app's existing HabitInput.
 * App-side only (uses the app's types); the habit ID is generated by the app on
 * create, never taken from `blueprintId`. Metrics history isn't part of a blueprint.
 */
import { type HabitInput } from '@/features/habits/habit.types';

import { COLOR_TOKENS, ICON_TOKENS, READ_MORE_PROFILE } from './catalog';
import { type HabitBlueprintV1 } from './blueprint.types';

export function blueprintToHabitInput(blueprint: HabitBlueprintV1): HabitInput {
  const minutes = blueprint.metrics.find((m) => m.id === 'reading_minutes');
  return {
    type: blueprint.habit.direction,
    template: READ_MORE_PROFILE.appTemplate,
    targetMinutes: minutes?.goal?.value ?? null,
    name: blueprint.habit.name,
    icon: ICON_TOKENS[blueprint.presentation.icon],
    color: COLOR_TOKENS[blueprint.presentation.colorToken],
    scheduleDays: [...blueprint.habit.schedule.days],
    reminderTime: blueprint.habit.reminder?.localTime ?? null,
  };
}
